  "author": "Matt Harris <mharris@vultr.com>",
  "maintainers": [
    "Matt Harris <mharris@vultr.com>"
  ],
  "license": "MIT",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vultr",
    "model-provider"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vultr/model-provider-opencode.git"
  },
